def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row if v != 1)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            reaches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    reaches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not reaches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out
